import{_ as t,o,c as a,a4 as r}from"./chunks/framework.BbWJDUyc.js";const m=JSON.parse('{"title":"What is JUCE?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-juce.md","filePath":"guide/what-is-juce.md","lastUpdated":null}'),i={name:"guide/what-is-juce.md"};function s(n,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="what-is-juce" tabindex="-1">What is JUCE? <a class="header-anchor" href="#what-is-juce" aria-label="Permalink to &quot;What is JUCE?&quot;">​</a></h1><p><strong>JUCE is a cross-platform C++ framework for building audio applications, audio plug-ins, and the GUIs that go with them.</strong> You write your program once against JUCE&#39;s classes and it compiles for macOS, Windows, Linux, iOS, and Android. The same code can also be wrapped as a VST3, AU, AUv3, AAX, or LV2 plug-in.</p><p>The name began as <em>Jules&#39; Utility Class Extensions</em>, after its original author, Julian &quot;Jules&quot; Storer. It is now maintained by the JUCE team at PACE Anti-Piracy (see <a href="./history.html">History</a>).</p><h2 id="what-problem-does-it-solve" tabindex="-1">What problem does it solve? <a class="header-anchor" href="#what-problem-does-it-solve" aria-label="Permalink to &quot;What problem does it solve?&quot;">​</a></h2><p>Writing audio software means dealing with several hard problems at once:</p><table tabindex="0"><thead><tr><th>Problem</th><th>Without JUCE</th><th>With JUCE</th></tr></thead><tbody><tr><td><strong>Audio I/O</strong></td><td>CoreAudio, WASAPI, ASIO, ALSA, JACK, Oboe… each with its own API and threading rules</td><td>One <code>AudioDeviceManager</code> and one callback</td></tr><tr><td><strong>Plug-in formats</strong></td><td>A separate SDK and wrapper per format (VST3, AU, AAX, LV2) and per host quirk</td><td>Write one <code>AudioProcessor</code>; JUCE generates each format</td></tr><tr><td><strong>GUI</strong></td><td>Cocoa, Win32, X11/Wayland, UIKit, Android views</td><td>One <code>Component</code> tree drawn with one <code>Graphics</code> API</td></tr><tr><td><strong>Everything else</strong></td><td>Strings, files, threads, networking, XML/JSON, maths</td><td><code>juce_core</code>, one consistent library</td></tr></tbody></table><p>The trade-off: JUCE is a <em>framework</em>, so it owns the event loop and the application lifecycle. You fill in the parts it calls, rather than calling it from your own <code>main()</code>.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li><strong>24 modules</strong> of C++ source (see the <a href="./../reference/module-map.html">module map</a>). Each is a folder you add to your build; there are no pre-built binaries.</li><li><strong>Tools</strong> in <code>extras/</code>: <ul><li><strong>Projucer</strong>, a project generator and editor (the older way to configure projects)</li><li><strong>AudioPluginHost</strong>, a small host for testing plug-ins</li><li><strong>UnitTestRunner</strong>, <strong>BinaryBuilder</strong>, and <strong>AudioPerformanceTest</strong></li></ul></li><li><strong>CMake API</strong> (<code>juce_add_plugin</code>, <code>juce_add_gui_app</code>, …), the modern way to build (see <a href="./build-systems.html">Build systems</a>).</li><li><strong>Examples</strong> in <code>examples/</code>, including the <strong>DemoRunner</strong> app that bundles most demos.</li></ul><h2 id="the-five-ideas-that-explain-most-of-juce" tabindex="-1">The five ideas that explain most of JUCE <a class="header-anchor" href="#the-five-ideas-that-explain-most-of-juce" aria-label="Permalink to &quot;The five ideas that explain most of JUCE&quot;">​</a></h2><ol><li><strong>Everything is a module.</strong> Modules are layered: <code>juce_core</code> at the bottom, plug-in wrappers at the top. Each module lists its dependencies in its header. → <a href="./architecture.html">Architecture</a></li><li><strong>Two important threads.</strong> The <em>message thread</em> runs the GUI and events; the <em>audio thread</em> runs your DSP and must never block. Much of JUCE&#39;s design exists to move data safely between them. → <a href="./core-concepts.html#threads">Core concepts</a></li><li><strong>Components draw themselves.</strong> A GUI is a tree of <code>Component</code> objects, each with <code>paint()</code> and <code>resized()</code>. → <a href="./core-concepts.html#components">Core concepts</a></li><li><strong>An <code>AudioProcessor</code> is the unit of audio work.</strong> Plug-ins, graph nodes, and hosted third-party plug-ins all share this interface. → <a href="./plugin-anatomy.html">Anatomy of a plug-in</a></li><li><strong>State lives in trees.</strong> <code>ValueTree</code> plus listeners gives you undo, serialisation, and UI binding almost for free. → <a href="./core-concepts.html#state">Core concepts</a></li></ol><h2 id="who-uses-it" tabindex="-1">Who uses it? <a class="header-anchor" href="#who-uses-it" aria-label="Permalink to &quot;Who uses it?&quot;">​</a></h2><p>JUCE is widely used for commercial audio plug-ins, DAWs, and music apps. It also turns up in research, education, and embedded audio devices. Its strength is audio; you can build general desktop apps with it, but most of its design choices are made with real-time audio in mind.</p><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><p>The JUCE modules are dual-licensed:</p><ul><li><strong>AGPLv3.</strong> Free to use, but if you distribute your software (or let people use it over a network), you must release its source under the AGPLv3 as well.</li><li><strong>Commercial JUCE licence.</strong> Governed by the <a href="https://juce.com/legal/juce-9-licence/" target="_blank" rel="noreferrer">JUCE 9 End User Licence Agreement</a>. You need this for closed-source products. The <a href="https://juce.com/get-juce/#licensing-faq" target="_blank" rel="noreferrer">licensing FAQ</a> explains the available tiers.</li></ul><p>The examples use the permissive ISC licence. Bundled third-party code keeps its own licence, listed in the SPDX bill of materials (<code>JUCE.spdx.json</code>). Plug-in SDKs such as AAX have their own agreements too. See <a href="https://github.com/andrewh/JUCE/blob/master/LICENSE.md" target="_blank" rel="noreferrer"><code>LICENSE.md</code></a>.</p><div class="tip custom-block"><p class="custom-block-title">For this learning project</p><p>Studying and experimenting under the AGPLv3 is fine. If you later ship a closed-source product, you will need a commercial licence.</p></div><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>For how the pieces relate: <a href="./architecture.html">Architecture</a></li><li>For the vocabulary: <a href="./../reference/glossary.html">Glossary</a></li><li>For a structured way to study: <a href="./learning-path.html">Learning path</a></li></ul>',20)])])}const p=t(i,[["render",s]]);export{m as __pageData,p as default};
